package com.masterclass.inventory.service; import com.masterclass.inventory.dto.SaleDtos.*; import com.masterclass.inventory.entity.*; import com.masterclass.inventory.exception.BusinessException; import com.masterclass.inventory.mapper.SaleMapper; import com.masterclass.inventory.repository.*; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import java.math.BigDecimal; import java.util.*; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class SaleServiceTest { @Mock ProductRepository products; @Mock SaleRepository sales; @Mock InventoryMovementRepository movements; @Mock SaleMapper mapper; @InjectMocks SaleService service; @Test void rejectsWhenStockIsInsufficient(){ Product p=Product.builder().id(1L).sku("X").status(ProductStatus.ACTIVE).currentStock(1).unitPrice(BigDecimal.TEN).build(); when(products.findById(1L)).thenReturn(Optional.of(p)); assertThatThrownBy(()->service.create(new SaleRequest(List.of(new SaleItemRequest(1L,2))))).isInstanceOf(BusinessException.class); verify(sales,never()).save(any()); } }
